+BOOST_AUTO_TEST_CASE(write_uses_rename)
+{
+    const fs::path banlist_path{m_args.GetDataDirBase() / "banlist_atomic"};
+    CBanDB bandb{banlist_path};
+
+    banmap_t bans_write;
+    CBanEntry entry{/*nCreateTimeIn=*/100};
